/**  A needed font the library has. */
export type NeededFontMatch = {
	/**  The needed font, as asked. */
	font: NeededFont,
	/**
	 *  The face that stands for it. Of several faces that match, an active
	 *  face wins, then a healthy one, then the lowest face id; a broken face
	 *  is never matched.
	 */
	face: FaceId,
	/**  The name that found it. */
	matchedBy: NeededFontRule,
};

/**
 *  Which name found a needed font, in the order the names are tried. Names
 *  compare ignoring case and surrounding space.
 */
export type NeededFontRule = 
/**  The PostScript name (name ID 6). */
"postscriptName" | 
/**  The full name (name ID 4). */
"fullName" | 
/**
 *  The typographic family and subfamily (name IDs 16 and 17; 17 is 2
 *  when the font has no 17).
 */
"typographicFamily" | 
/**  The legacy family and subfamily (name IDs 1 and 2). */
"family";

/**
 *  A face [`ActivationService::document_closed`] offers, with the names a
 *  plugin shows for it (E30.5).
 */
export type OfferedFace = {
	/**  The face. */
	face: FaceId,
	/**  Its family name, as the library groups it. */
	family: string,
	/**  Its style name. */
	style: string,
	/**  Its PostScript name; `None` when the font declares none. */
	postscriptName: string | null,
};

/**  An open-source license recognized from the license text. */
export type OpenLicense = 
/**  SIL Open Font License. */
"ofl" | 
/**  Apache License 2.0. */
"apache" | 
/**  Ubuntu Font Licence. */
"ufl" | 
/**  MIT. */
"mit";

/**  What happened to one face. */
export type OutcomeStatus = 
/**  Now active (or now inactive, for a deactivation). */
{ status: "done" } | 
/**  Already in the requested state. */
{ status: "unchanged" } | 
/**  Not done because of a clash (with `KeepExisting`). */
{ status: "conflict"; 
/**  What it clashes with. */
with: ConflictWith } | 
/**  Not done: the app did not register it, or the format cannot be activated. */
{ status: "skipped"; 
/**  Why, in plain words. */
reason: string } | 
/**  The OS call failed. */
{ status: "failed"; 
/**  The error. */
error: ApiError };

/**  A window into a long list. `limit` is capped by the service (500). */
export type Page = {
	/**  Rows to skip. */
	offset: number,
	/**  Rows to return. */
	limit: number,
};

/**  One page of results and the size of the whole list. */
export type Paged<T> = {
	/**  The rows in this page. */
	items: T[],
	/**  Rows in the whole list. */
	total: number,
};

/**  A side of a folder pair. */
export type PairSide = 
/**  The side named `a`. */
"a" | 
/**  The side named `b`. */
"b";

/**  Faces that pair well with this one (E23.4). */
export type PairingRequest = {
	/**
	 *  The face to find partners for. With `partner_of` set, the face being
	 *  replaced instead: its family is not suggested.
	 */
	face: FaceId,
	/**  Suggestions to return. */
	limit: number,
	/**
	 *  The role the suggested faces play, which changes how they are scored
	 *  and the reasons given (ADR 0021). Absent: the plain rules, for no
	 *  role in particular.
	 */
	role?: PairingRole | null,
	/**
	 *  The face the suggestions must go with, when that is not `face`:
	 *  "given this body face, suggest headlines". A face that is not visible
	 *  is `NotFound`.
	 */
	partnerOf?: FaceId | null,
};

/**  The part a suggested face plays in a layout (E42.13). */
export type PairingRole = 
/**  Large type: a title or a heading. */
"headline" | 
/**  Running text. */
"body" | 
/**  Small type: a note or a label. */
"caption";

/**  A face suggested as a partner and why. */
export type PairingSuggestion = {
	/**  The face: one per family, the style closest to the one asked about. */
	face: FaceSummary,
	/**  0.0–1.0; higher pairs better. */
	score: number | null,
	/**
	 *  Plain-word reasons, one per rule that holds ("same superfamily"); with
	 *  a role in the request, those of the role first ("lower contrast for
	 *  body", "x-height within 4 %").
	 */
	reasons: string[],
};

/**
 *  One `CPAL` palette of a `COLR` color face (E16.3). The webview applies it
 *  with CSS `font-palette` (`base-palette: index`).
 */
export type Palette = {
	/**  Index of the palette in the `CPAL` table (0 is the default). */
	index: number,
	/**  The palette's name from the `name` table, if the font gives one. */
	name: string | null,
	/**
	 *  Its colors as CSS hex, in palette-entry order: `#rrggbb`, or
	 *  `#rrggbbaa` when the color is not opaque.
	 */
	colors: string[],
	/**  The font marks it for use on a light background. */
	lightBackground: boolean,
	/**  The font marks it for use on a dark background. */
	darkBackground: boolean,
};

/**
 *  Pin an instance of a variable face as a virtual style of a manual
 *  collection or a project set: exactly one of `collection` and `set`.
 */
export type PinInstanceRequest = {
	/**  The variable face. */
	face: FaceId,
	/**
	 *  Style name ("Condensed Semibold"); unique per face in its collection
	 *  or set.
	 */
	name: string,
	/**  Axis coordinates; an axis left out is at its default. */
	coordinates?: AxisValue[],
	/**  The manual collection that holds it. */
	collection?: CollectionId | null,
	/**  The project set that holds it. */
	set?: SetId | null,
};

/**  Plan a cleanup ([`crate::LibraryService::plan_cleanup`]). */
export type PlanCleanupRequest = {
	/**  The sets to plan; the whole library by default. */
	scope?: CleanupScope,
	/**
	 *  The keepers the user picked; every other set follows the saved keeper
	 *  policy and the language guard.
	 */
	keepers?: CleanupKeeper[],
	/**  How the copies leave. */
	removeAs?: RemoveAs,
	/**
	 *  Move the activation of an active copy of an identical set to the
	 *  kept copy, so that copy can leave too. Off: an active copy stays.
	 */
	moveActivations?: boolean,
};

/**  The operating system the app runs on. */
export type Platform = 
/**  Windows 10 or 11. */
"windows" | 
/**  macOS. */
"macos" | 
/**  Linux. */
"linux";

/**  Activate a family, subset it and return its CSS. */
export type PrepareForWebRequest = {
	/**  The family. */
	family: FamilyId,
	/**  Subset; the full character set when absent. */
	subset?: Subset | null,
	/**  Output folder. */
	outDir: string,
};

/**  What `prepare_for_web` did. */
export type PrepareForWebResponse = {
	/**  Session activation, per face. */
	activated: ActivationOutcome[],
	/**  The export. */
	export: ExportWebResponse,
};

/**  A rendered preview. */
export type PreviewImage = {
	/**  Width in pixels. */
	width: number,
	/**  Height in pixels. */
	height: number,
	/**  PNG bytes. */
	png: number[],
};

/**
 *  Preview a keeper policy without saving it
 *  ([`LibraryService::preview_keeper_policy`]).
 */
export type PreviewKeeperPolicyRequest = {
	/**  The sets to look at, as [`ListDuplicateSetsRequest::scope`]. */
	scope?: DuplicateScope,
	/**  The policy to try. */
	policy: KeeperPolicy,
};

/**  Render a line of text in one face. */
export type PreviewRequest = {
	/**  The face. */
	face: FaceId,
	/**  The text. */
	text: string,
	/**  Size in pixels (8–300). */
	sizePx: number | null,
	/**  Variation coordinates; defaults for unlisted axes. */
	variations?: AxisValue[],
	/**  Features switched on or off. */
	features?: FeatureSetting[],
	/**  Text color, CSS hex (`#1a1a1a`); black when absent. */
	foreground?: string | null,
	/**  Background color, CSS hex; transparent when absent. */
	background?: string | null,
};

/**  One entry of the Problems view. */
export type Problem = {
	/**  What kind. */
	kind: ProblemKind,
	/**  The face, when the file parsed far enough to have one. */
	face: FaceId | null,
	/**  The file. */
	path: string,
	/**  The other face or file it clashes with, for duplicates and conflicts. */
	other: string | null,
	/**  One sentence for the user. */
	message: string,
};

/**  What kind of health problem. */
export type ProblemKind = 
/**  The same file (same hash) at two paths. */
"duplicateFile" | 
/**  The same family, style and version at different paths. */
"duplicateFace" | 
/**  Truncated or missing required tables. */
"broken" | 
/**  No Unicode `cmap`. */
"noUnicodeCmap" | 
/**  Same PostScript name as a system font. */
"systemConflict" | 
/**  Same PostScript name as a font already active from another source. */
"activeConflict" | 
/**  A format the app cannot activate. */
"unsupported" | 
/**
 *  Sidecar metadata (`<source>/.fontlibrary/`) that could not be merged:
 *  another machine set a field to a different value, or the sidecar file
 *  cannot be read. Nothing is overwritten until the user decides.
 */
"sidecarConflict" | 
/**
 *  A source folder that is not there (removed, renamed, an unplugged
 *  drive). Its faces stay in the index until the user removes the source.
 */
"missingSource" | 
/**
 *  The library index file was damaged and a fresh one replaced it; the
 *  damaged file was kept aside and the sources are scanned again.
 */
"indexRebuilt";

/**  A project set: fonts activated together. */
export type ProjectSet = {
	/**  Id. */
	id: SetId,
	/**  Name. */
	name: string,
	/**  The faces. */
	faces: FaceId[],
};

/**
 *  Why a folder can be the kept side of a pair and never the removed side
 *  as a whole (E56.6).
 */
export type ProtectedFolder = 
/**  The folder is the root of a source the user added. */
"sourceRoot" | 
/**  The folder is, or is inside, a system font folder (rule 4). */
"systemFolder" | 
/**  The folder is the library folder. */
"libraryFolder";

/**
 *  The Quick Collection (E13.3): one list of faces the user gathers while
 *  browsing, to review and then keep as a collection or a tag. It is kept in
 *  the index, so it outlives a restart.
 */
export type QuickCollection = {
	/**
	 *  Its faces in the order they were added, first added first. A face
	 *  the library does not show (its file is gone, its source paused) is
	 *  left out while it is hidden.
	 */
	faces: FaceSummary[],
};

/**  Add faces to, or remove them from, the Quick Collection. */
export type QuickCollectionRequest = {
	/**
	 *  The faces. Adding a face already in it keeps its place; removing a
	 *  face not in it does nothing.
	 */
	faces: FaceId[],
};

/**  What [`LicenseDeclaration`] does to a family's receipt. */
export type ReceiptChange = 
/**  Leave the receipt as it is. */
{ kind: "keep" } | 
/**  Remove the receipt: the copy the app made goes to the OS trash. */
{ kind: "clear" } | 
/**
 *  Attach a copy of the file at `path`; the file itself is never moved.
 *  A receipt attached before goes to the OS trash. A file that is not
 *  there is `InvalidRequest`.
 */
{ kind: "attach"; 
/**  The receipt file the user picked. */
path: string; 
/**  Where the copy goes. */
place: ReceiptPlace };

/**  Where the app keeps the copy of a receipt. */
export type ReceiptPlace = 
/**
 *  Next to the font, in its source folder's `.fontlibrary/` folder, so a
 *  synced folder carries it to teammates. A system font folder is
 *  `InvalidRequest`.
 */
"nextToFont" | 
/**  In the app's data folder, on this machine only. */
"appData";

/**  Which recommendation a listed set has (E56.11). */
export type RecommendationFilter = 
/**  The policy recommends removing at least one copy. */
"hasRecommendation" | 
/**  The policy answered the set "keep both" ([`KeeperOutcome::KeepBoth`]). */
"keepBoth";

/**  How a copy leaves the library. */
export type RemoveAs = 
/**  The file goes to the OS trash (ADR 0009). */
"trash" | 
/**  The file stays where it is and leaves the library (E56.8). */
"hide";

/**
 *  One copy the recommendation would remove, with the rule it lost by
 *  against the keeper.
 */
export type RemovedCopy = {
	/**  Absolute file path. */
	path: string,
	/**  The rule that put the keeper before it. */
	reason: KeeperReason,
};

/**  Rename a collection, or change its colour. */
export type RenameCollectionRequest = {
	/**  The collection. */
	collection: CollectionId,
	/**  New name; its current name changes only the colour. */
	name: string,
	/**
	 *  A key of [`COLLECTION_COLORS`] sets the colour and an empty string
	 *  removes it; absent keeps it, so a plain rename leaves it alone. Any
	 *  other value is `InvalidRequest`.
	 */
	color?: string | null,
};

/**  Gives a saved comparison a new name. */
export type RenameComparisonRequest = {
	/**  Id. */
	id: ComparisonId,
	/**  The new name; must not be empty. */
	name: string,
};

/**
 *  A "Keep this one" action: the copy kept and the copies moved to the
 *  trash. Listed in the Problems history until undone or forgotten.
 */
export type Resolution = {
	/**
	 *  The action, for [`LibraryService::undo_resolution`]; `None` for a dry
	 *  run or when nothing moved.
	 */
	id: ResolutionId | null,
	/**  The copy kept. */
	kept: string,
	/**  When it happened. */
	at: string,
	/**  It was a dry run: nothing moved. */
	dryRun: boolean,
	/**  Every moved copy was put back. */
	undone: boolean,
	/**  The copies, in the order of the request. */
	moves: TrashMove[],
};

/**  A "Keep this one" action of the Problems view, for undo. */
export type ResolutionId = number;

/**  A `<font>` argument to look up (E26.1): a face id or a name. */
export type ResolveFontRequest = {
	/**
	 *  A face id (`42`) or a name: a PostScript name, a full name, or a
	 *  family with or without its style.
	 */
	font: string,
};

/**  Resolves one sidecar conflict. */
export type ResolveSidecarConflictRequest = {
	/**  The conflict. */
	id: SidecarConflictId,
	/**  The value to keep. */
	keep: ConflictSide,
};

/**  Makes an earlier version current again. */
export type RestoreLayoutRequest = {
	/**  The template file's id. */
	id: string,
	/**  The [`LayoutVersion::number`] to restore. */
	number: number,
};

/**  Goes back to the saved file, or a preset back to its shipped original. */
export type RevertLayoutRequest = {
	/**  The template file's id. */
	id: string,
	/**
	 *  Writes the shipped original of the layout's preset (the content it
	 *  replaces is kept as a version); false only reads the saved file.
	 */
	toOriginal?: boolean,
};

/**  One rule of a [`RuleGroup`]. */
export type Rule = 
/**
 *  A face passes when it passes these filters, as search applies them.
 *  `collection` may name another smart collection: its rule applies
 *  (a rule that reaches its own collection is `InvalidRequest`).
 */
{ kind: "filters"; 
/**  The filters. */
filters: Filters } | 
/**  A nested group. */
{ kind: "group"; 
/**  The group. */
group: RuleGroup };

/**
 *  A smart collection's rule: a group of rules combined with AND or OR. A
 *  group with no rules passes every face.
 */
export type RuleGroup = {
	/**  AND or OR. */
	op: RuleOp,
	/**  The rules. */
	rules?: Rule[],
};

/**  How a [`RuleGroup`] combines its rules. */
export type RuleOp = 
/**  A face must pass every rule. */
"and" | 
/**  A face must pass at least one rule. */
"or";

/**  Why a face previews other text than the sample. */
export type SampleFallback = 
/**  Letters of a script the face covers. */
{ kind: "script"; 
/**  ISO 15924 script (`Cyrl`). */
script: string } | 
/**  Characters the face maps, for a face that covers no language. */
{ kind: "symbols" };

/**  The text one face previews. */
export type SampleText = {
	/**  The face. */
	face: FaceId,
	/**  The sample text, or text from the face's own coverage. */
	text: string,
	/**  Set when the face lacks characters of the sample and `text` is other text. */
	fallback?: SampleFallback | null,
	/**  The characters of the sample the face lacks. */
	missing?: string[],
};

/**  The text to preview some faces with, for one sample text. */
export type SampleTextRequest = {
	/**  The faces. */
	faces: FaceId[],
	/**  The sample text the user chose. */
	text: string,
};

/**  Saves a comparison: a new one, or over an existing one. */
export type SaveComparisonRequest = {
	/**  The comparison to overwrite; none saves a new one. */
	id?: ComparisonId | null,
	/**  Its name; must not be empty (spaces around it are dropped). */
	name: string,
	/**  2–4 distinct faces, in the order the sheet shows them. */
	faces: FaceId[],
	/**  The mode. */
	mode?: CompareMode,
	/**  The sample text; empty means each face shows its own name. */
	sampleText?: string,
};

/**  Writes a layout to its template file; the previous content is kept as a version. */
export type SaveLayoutRequest = {
	/**  The template file's id; a new id makes a new file. */
	id: string,
	/**  The layout; its values are clamped before they are written. */
	layout: Layout,
};

/**
 *  Save a project set as a set file (E28.2): its [`SetExport`] JSON, at a
 *  path the user picked.
 */
export type SaveSetFileRequest = {
	/**  The set. */
	set: SetId,
	/**
	 *  Absolute file path. A file name with no extension gets
	 *  [`SET_FILE_EXTENSION`].
	 */
	path: string,
};

/**  A layout as it is saved in its template file. */
export type SavedLayout = {
	/**  The template file's id. */
	id: string,
	/**  The saved layout, clamped into the block ranges. */
	layout: Layout,
};

/**  A set file that was written. */
export type SavedSetFile = {
	/**  The path written, its extension added when it had none. */
	path: string,
	/**  The number of fonts in it. */
	fonts: number,
};

/**  Start a scan. Returns at once; progress arrives as `Event::ScanProgress`. */
export type ScanRequest = {
	/**  One source, or every source when absent. */
	source?: SourceId | null,
};

/**  A search. An empty query with filters lists everything that passes them. */
export type SearchRequest = {
	/**
	 *  Free text over family, style, PostScript name, foundry, designer, tags
	 *  and file name; typo-tolerant; style words ("bold italic") narrow styles.
	 */
	query?: string,
	/**  Filters. */
	filters?: Filters,
	/**
	 *  A smart-collection rule a face must pass as well, as a smart
	 *  collection applies it (E14.1: the rule editor's live count of a rule
	 *  not saved yet).
	 */
	rule?: RuleGroup | null,
	/**  The order of the family groups; `None`: best match first. */
	order?: FamilyOrder | null,
	/**  Window over the family groups. */
	page?: Page,
	/**
	 *  Glyph traits every result face must have (E49.5), from
	 *  `list_glyph_traits`; they combine with AND, with each other and with
	 *  the filters. A face without a detection of the trait (it lacks the
	 *  glyph, or it is not measured yet) passes no trait filter.
	 */
	glyphTraits?: TraitFilter[] | null,
	/**
	 *  Sorts the families by how close their drawing of one character is to
	 *  a reference face's (E49.9, "an R like this one"): each family by its
	 *  closest matching face, closest first; families none of whose matching
	 *  faces draws the character follow in the default order. When set it
	 *  decides the order and `order` is not used; the filters, the query and
	 *  the glyph traits still choose the families. A reference face that is
	 *  unknown or does not draw the character is `NotFound`.
	 */
	likeGlyph?: GlyphReference | null,
	/**
	 *  Families of any of these foundries (E50.11), by the canonical names
	 *  `list_foundries` gives, compared without case or punctuation;
	 *  [`UNKNOWN_FOUNDRY`] names the faces with no foundry. Like the glyph
	 *  traits, a face outside them is no result and counts under no filter
	 *  value. `None` or an empty list: every foundry.
	 */
	foundries?: string[] | null,
	/**
	 *  Only these faces (E51.2: "Show" on the notice of fonts the folder
	 *  watcher added). Like the foundries, a face outside them is no result
	 *  and counts under no filter value; an unknown id matches nothing.
	 *  `None`: every face. An empty list: no face.
	 */
	faces?: FaceId[] | null,
};

/**  Search results grouped by family. */
export type SearchResponse = {
	/**  Family groups in this page. */
	families: FamilyHit[],
	/**  Family groups in all pages. */
	total: number,
	/**  The result count of every filter value. */
	counts?: FilterCounts | null,
};

/**  One tag of a [`SelectionTags`]. */
